import sys

MOD = 1000000007

def multiply(a, b, m):
    res = [[0] * m for _ in range(m)]
    for i in range(m):
        for k in range(m):
            aik = a[i][k]
            if aik == 0:
                continue
            for j in range(m):
                res[i][j] = (res[i][j] + aik * b[k][j]) % MOD
    return res

def power(exp, base, m):
    res = [[0] * m for _ in range(m)]
    for i in range(m):
        res[i][i] = 1
    while exp > 0:
        if exp & 1:
            res = multiply(res, base, m)
        base = multiply(base, base, m)
        exp >>= 1
    return res

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    m = int(data[1])

    if n < m:
        print(1)
        return
    if n == m:
        print(2)
        return

    mat = [[0] * m for _ in range(m)]
    mat[0][0] = 1
    mat[0][m - 1] = 1
    for i in range(1, m):
        mat[i][i - 1] = 1

    result_mat = power(n, mat, m)
    print(result_mat[0][0])

if __name__ == "__main__":
    main()

